from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

import bpy

from terrain_layers.masks.mask_types.type_helpers import MaskSocket
from terrain_layers.utility.type_helpers import Node


@dataclass(frozen=True, slots=True)
class ScatterFootprintMask:
    """A soft terrain mask around points generated by a scatter biome."""

    type: Literal["scatter_footprint"] = "scatter_footprint"
    scatter_biome_id: str = ""
    inner_radius: float = 0.75
    outer_radius: float = 1.5


def add_scatter_footprint_mask_node(
    nt: bpy.types.NodeTree,
    mask_def: ScatterFootprintMask,
    *,
    points: bpy.types.NodeSocket,
) -> tuple[MaskSocket, list[Node]]:
    """Build a 1→0 radial falloff from a biome's generated point cloud."""
    nodes, links = nt.nodes, nt.links

    position = nodes.new("GeometryNodeInputPosition")
    proximity = nodes.new("GeometryNodeProximity")
    proximity.target_element = "POINTS"
    proximity.label = f"Footprint Points: {mask_def.scatter_biome_id}"
    # Geometry Proximity was renamed from Target/Source Position to
    # Geometry/Sample Position in newer Blender versions.
    target_input = proximity.inputs.get("Geometry") or proximity.inputs.get("Target")
    sample_position_input = (
        proximity.inputs.get("Sample Position")
        or proximity.inputs.get("Source Position")
    )
    if target_input is None or sample_position_input is None:
        raise RuntimeError("Geometry Proximity node is missing required inputs.")
    links.new(points, target_input)
    links.new(position.outputs["Position"], sample_position_input)

    falloff = nodes.new("ShaderNodeMapRange")
    falloff.clamp = True
    falloff.interpolation_type = "LINEAR"
    falloff.label = "Footprint Radius & Falloff"
    falloff.inputs["From Min"].default_value = float(mask_def.inner_radius)
    falloff.inputs["From Max"].default_value = float(mask_def.outer_radius)
    falloff.inputs["To Min"].default_value = 1.0
    falloff.inputs["To Max"].default_value = 0.0
    links.new(proximity.outputs["Distance"], falloff.inputs["Value"])

    return falloff.outputs["Result"], [position, proximity, falloff]
